import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry with atlas region aspect ratio (512x320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1, 1, 1);

  // Create material with texture node
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Store reference for async texture load
  let textureLoaded = false;

  // Load texture and apply UV offset for atlas region
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.minFilter = THREE.LinearFilter;
      texture.magFilter = THREE.LinearFilter;

      // Atlas region: 0,0,512,320 in a larger atlas
      // Assuming standard atlas layout, apply UV transform
      const uvNode = uv();
      const atlasUvNode = vec2(
        uvNode.x * (512 / 512),  // width ratio
        uvNode.y * (320 / 320)   // height ratio
      );

      // Assign color output with texture
      material.colorNode = texture.uv(atlasUvNode);
      material.needsUpdate = true;
      textureLoaded = true;
    });
  }

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.copy(new THREE.Vector3(
    config.scenePosition?.[0] ?? 0,
    config.scenePosition?.[1] ?? -0.35,
    config.scenePosition?.[2] ?? -0.6
  ));

  // Ensure billboard orientation (face camera)
  mesh.lookAt(new THREE.Vector3(0, 0, 1));

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
